import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Installing mods from mainland China","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Mod-download-in-China.md","filePath":"UncivCN/Mod-download-in-China.md"}'),n={name:"UncivCN/Mod-download-in-China.md"};function r(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="installing-mods-from-mainland-china" tabindex="-1">Installing mods from mainland China <a class="header-anchor" href="#installing-mods-from-mainland-china" aria-label="Permalink to &quot;Installing mods from mainland China&quot;">​</a></h1><blockquote><p>Author: UncivCN</p><p>Last updated: see git history</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>Almost all Unciv mods are published on GitHub, and the in-game mod browser searches, previews and downloads mods through GitHub&#39;s services. Access to GitHub from mainland China is unreliable: the mod list often fails to load and downloads frequently break. This makes installing mods very hard for players in China.</p><p>UncivCN ships a built-in <strong>download source</strong> switch to solve exactly this problem. The source is not only used for the mod list, preview images and downloads - the in-game update check (querying the latest GitHub release) goes through the same source.</p><h2 id="in-game-solution-switch-the-download-source" tabindex="-1">In-game solution: switch the download source <a class="header-anchor" href="#in-game-solution-switch-the-download-source" aria-label="Permalink to &quot;In-game solution: switch the download source&quot;">​</a></h2><p>Open <strong>Options → Advanced</strong> from the main menu and find <strong>Download source</strong>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td>GitHub (official)</td><td>Default; connects directly to GitHub, usually unstable in mainland China</td></tr><tr><td>gh-proxy.com</td><td>Public GitHub proxy (tested to work for search, preview images and downloads)</td></tr><tr><td>ghfast.top</td><td>Public GitHub proxy</td></tr><tr><td>ghproxy.net</td><td>Public GitHub proxy</td></tr><tr><td>Custom</td><td>Enter your own proxy prefix in the input field below</td></tr></tbody></table><p>After switching, go back to the <strong>Mod Management</strong> screen (re-entering the screen refreshes it) - the mod list, preview images and downloads will all go through the selected mirror.</p><h3 id="automatic-guidance" tabindex="-1">Automatic guidance <a class="header-anchor" href="#automatic-guidance" aria-label="Permalink to &quot;Automatic guidance&quot;">​</a></h3><p>If loading the mod list fails, the game checks the currently active download source:</p><ul><li>If it is still the official source, a confirmation popup offers to <strong>switch to the mirror source (gh-proxy.com) and retry automatically</strong> - just confirm;</li><li>If a mirror is already active and it still fails, a toast points to Options → Advanced to try another mirror.</li></ul><h3 id="custom-prefix" tabindex="-1">Custom prefix <a class="header-anchor" href="#custom-prefix" aria-label="Permalink to &quot;Custom prefix&quot;">​</a></h3><p>Some players may run their own proxy or prefer a specific accelerator. Select Custom and type the prefix (e.g. <code>https://gh-proxy.com/</code>) into the input field, then press Enter to save. The prefix is prepended to GitHub URLs, i.e.:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-proxy-host/https://github.com/author/mod-repo/archive/refs/heads/main.zip</span></span></code></pre></div><p>Only GitHub-hosted URLs (github.com, raw.githubusercontent.com, avatars.githubusercontent.com, api.github.com etc.) get the prefix; other addresses (e.g. direct zip links on Gitee) are never touched.</p><h2 id="game-update-check" tabindex="-1">Game update check <a class="header-anchor" href="#game-update-check" aria-label="Permalink to &quot;Game update check&quot;">​</a></h2><p>On entering the main menu, the game queries the latest release of the UncivCN repository in the background (also through the active download source). When a newer version exists, the version label at the bottom of the main menu shows a &quot;New version available&quot; hint; clicking the version label shows the new version info and a link to the download page. If the check fails due to network problems, a confirmation popup offers a one-click switch to a mirror download source (same interaction as the mod list failure).</p><h2 id="manual-way-paste-an-accelerated-link" tabindex="-1">Manual way: paste an accelerated link <a class="header-anchor" href="#manual-way-paste-an-accelerated-link" aria-label="Permalink to &quot;Manual way: paste an accelerated link&quot;">​</a></h2><p>You can also install mods without switching the source. In Mod Management → &quot;Download mod from URL&quot;, paste an accelerated zip link, for example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gh-proxy.com/https://github.com/author/mod-repo/archive/refs/heads/main.zip</span></span></code></pre></div><p>Unciv can download and extract a mod zip from any URL, so repository links on other platforms such as Gitee work as well.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Public proxy services are free community offerings - they may be rate-limited, go down or change domains at any time. If a built-in mirror stops working, try another built-in one first, or search for a currently working GitHub accelerator and fill it in as a custom prefix.</p></div>',23)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
